use xiom.io;

type Book = {
  title: Str;
  author: Str;
  checked_out: Bool;
}

fn Book.checkout(self) {
  checked_out = true;
}

fn Book.is_available(self) -> Bool {
  return !checked_out;
}

fn Book.return_book(self) {
  checked_out = false;
}

fn main() -> Int {
  var book = Book{
    title: "The Hobbit";
    author: "J.R.R. Tolkien";
    checked_out: false;
  };
  book.checkout();
  let avail = book.is_available();
  book.return_book();
  let avail_after = book.is_available();
  return 0;
}
